/**
 * Rootz V6 Dashboard — Public Secret Viewer
 *
 * Self-contained module for viewing public (unencrypted) secrets via URL.
 * No wallet or signer required — read-only chain queries + IPFS fetch.
 *
 * Route: #/s/{secretAddress}
 *
 * Data flow:
 *   URL address → Etherscan getLogs (KeyVaultCreated event)
 *     → Parse encryptedKeysData (isPublic, plaintextIPFSHash, contentHash)
 *     → Fetch content from IPFS public gateway
 *     → Verify SHA-256 hash client-side
 *     → Render content + verification evidence
 *
 * For Document Wallet secrets (type: 'document-wallet'):
 *   → Parse manifest JSON from content
 *   → Show origin hash, AI layer hash, binding hash
 *   → Render AI markdown body
 */

import { loadConfig, type AppConfig } from './config';
import { AbiCoder, id as ethersId, toUtf8String } from 'ethers';

// Etherscan V2 unified API (supports Polygon via chainid param)
const ETHERSCAN_V2_API = 'https://api.etherscan.io/v2/api';

// IPFS public gateways (no API key needed)
const IPFS_GATEWAYS = [
  'https://gateway.pinata.cloud/ipfs/',
  'https://ipfs.io/ipfs/',
  'https://cloudflare-ipfs.com/ipfs/',
];

// KeyVaultCreated event signature
const KEY_VAULT_CREATED_SIG = ethersId('KeyVaultCreated(uint256,address,bytes,bytes,uint256)');

// ============================================
// Types
// ============================================

interface KeyVaultEvent {
  blockNumber: number;
  creator: string;
  encryptedKeysData: string;
  schemaDefinition: string;
  timestamp: number;
  txHash: string;
}

interface PublicKeyVaultData {
  isPublic: boolean;
  plaintextIPFSHash: string;
  contentHash: string;
  creator: {
    address: string;
    publicKey: string;
  };
  metadata: {
    secretName: string;
    secretType: string;
    contractAddress: string;
    createdAt: number;
    version: string;
    isPublic: boolean;
  };
}

interface IPFSContent {
  name: string;
  type: string;
  content: string;
  contractAddress: string;
  owner: string;
  isPublic: boolean;
  timestamp: number;
  createdAt: string;
  tags?: string[];
  description?: string;
  source?: string;
}

interface DocumentWalletManifest {
  type: string;
  title: string;
  author?: string;
  summary?: string;
  topics?: string[];
  aiMarkdown?: string;
  originHash?: string;
  aiLayerHash?: string;
  bindingHash?: string;
  filename?: string;
  mimeType?: string;
  walletAddress?: string;
  createdAt?: string;
}

interface VerificationState {
  contentHash: 'pending' | 'verified' | 'failed';
  ipfsFetch: 'pending' | 'verified' | 'failed';
  chainRead: 'pending' | 'verified' | 'failed';
}

// ============================================
// Chain Reading (minimal, no wallet deps)
// ============================================

async function fetchKeyVaultEvent(
  secretAddress: string,
  chainId: number,
  etherscanApiKey: string
): Promise<KeyVaultEvent | null> {
  const url = new URL(ETHERSCAN_V2_API);
  url.searchParams.set('chainid', chainId.toString());
  url.searchParams.set('module', 'logs');
  url.searchParams.set('action', 'getLogs');
  url.searchParams.set('apikey', etherscanApiKey);
  url.searchParams.set('address', secretAddress);
  url.searchParams.set('topic0', KEY_VAULT_CREATED_SIG);
  url.searchParams.set('fromBlock', '0');
  url.searchParams.set('toBlock', 'latest');

  const response = await fetch(url.toString());
  if (!response.ok) throw new Error(`Etherscan API error: ${response.status}`);

  const data = await response.json();
  if (data.status === '0' || typeof data.result === 'string' || data.result.length === 0) {
    return null;
  }

  const log = data.result[0];

  // topics[1] = indexed blockNumber (uint256)
  // topics[2] = indexed creator (address)
  const blockNumber = parseInt(log.topics[1], 16);
  const creator = '0x' + log.topics[2].slice(-40);

  // Decode non-indexed params: encryptedKeysData (bytes), schemaDefinition (bytes), timestamp (uint256)
  const abiCoder = new AbiCoder();
  const decoded = abiCoder.decode(['bytes', 'bytes', 'uint256'], log.data);

  return {
    blockNumber,
    creator: creator.toLowerCase(),
    encryptedKeysData: toUtf8String(decoded[0]),
    schemaDefinition: toUtf8String(decoded[1]),
    timestamp: Number(decoded[2]),
    txHash: log.transactionHash,
  };
}

// ============================================
// IPFS Fetching
// ============================================

async function fetchFromIPFS(ipfsHash: string): Promise<string> {
  for (const gateway of IPFS_GATEWAYS) {
    try {
      const response = await fetch(gateway + ipfsHash, { signal: AbortSignal.timeout(15000) });
      if (response.ok) {
        return await response.text();
      }
    } catch {
      // Try next gateway
    }
  }
  throw new Error(`Failed to fetch from IPFS: ${ipfsHash}`);
}

// ============================================
// Content Hash Verification
// ============================================

async function computeSHA256(content: string): Promise<string> {
  const encoder = new TextEncoder();
  const hashBuffer = await crypto.subtle.digest('SHA-256', encoder.encode(content));
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return 'sha256:' + hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

// ============================================
// Rendering
// ============================================

function escapeHtml(str: string): string {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}

function formatAddress(addr: string): string {
  return addr.slice(0, 6) + '...' + addr.slice(-4);
}

function formatTimestamp(ts: number): string {
  if (ts < 1e12) ts *= 1000; // Convert seconds to ms if needed
  return new Date(ts).toLocaleString();
}

function renderVerificationBadge(state: 'pending' | 'verified' | 'failed'): string {
  const icons = { pending: '&#8987;', verified: '&#10004;', failed: '&#10008;' };
  const classes = { pending: 'pv-badge-pending', verified: 'pv-badge-verified', failed: 'pv-badge-failed' };
  return `<span class="pv-badge ${classes[state]}">${icons[state]}</span>`;
}

function renderDocumentWalletContent(manifest: DocumentWalletManifest): string {
  const topicsHtml = manifest.topics?.length
    ? `<div class="pv-topics">${manifest.topics.map(t => `<span class="pv-topic">${escapeHtml(t)}</span>`).join('')}</div>`
    : '';

  const hashesHtml = `
    <div class="pv-hashes">
      <h3>Hash Binding</h3>
      ${manifest.originHash ? `<div class="pv-hash-row"><span class="pv-hash-label">Origin Hash</span><code>${escapeHtml(manifest.originHash)}</code></div>` : ''}
      ${manifest.aiLayerHash ? `<div class="pv-hash-row"><span class="pv-hash-label">AI Layer Hash</span><code>${escapeHtml(manifest.aiLayerHash)}</code></div>` : ''}
      ${manifest.bindingHash ? `<div class="pv-hash-row"><span class="pv-hash-label">Binding Hash</span><code>${escapeHtml(manifest.bindingHash)}</code></div>` : ''}
    </div>
  `;

  // Simple markdown-to-HTML (basic: headers, bold, italic, code, lists, paragraphs)
  const markdownHtml = manifest.aiMarkdown
    ? simpleMarkdown(manifest.aiMarkdown)
    : '<p class="pv-no-content">No AI markdown content</p>';

  return `
    <div class="pv-doc-wallet">
      <div class="pv-doc-header">
        <h2>${escapeHtml(manifest.title)}</h2>
        ${manifest.author ? `<div class="pv-doc-author">By ${escapeHtml(manifest.author)}</div>` : ''}
        ${manifest.summary ? `<div class="pv-doc-summary">${escapeHtml(manifest.summary)}</div>` : ''}
        ${topicsHtml}
        ${manifest.filename ? `<div class="pv-doc-file">Origin: <code>${escapeHtml(manifest.filename)}</code> (${escapeHtml(manifest.mimeType || 'unknown')})</div>` : ''}
      </div>
      ${hashesHtml}
      <div class="pv-doc-body">
        <h3>Document Content</h3>
        ${markdownHtml}
      </div>
    </div>
  `;
}

/** Simple markdown to HTML converter (no external deps) */
function simpleMarkdown(md: string): string {
  let html = escapeHtml(md);

  // Code blocks (```)
  html = html.replace(/```(\w*)\n([\s\S]*?)```/g, '<pre><code>$2</code></pre>');
  // Inline code
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
  // Headers
  html = html.replace(/^#### (.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');
  // Bold and italic
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
  // Unordered lists
  html = html.replace(/^- (.+)$/gm, '<li>$1</li>');
  html = html.replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>');
  // Horizontal rule
  html = html.replace(/^---$/gm, '<hr>');
  // Paragraphs (double newlines)
  html = html.replace(/\n\n/g, '</p><p>');
  html = '<p>' + html + '</p>';
  // Clean up empty paragraphs
  html = html.replace(/<p>\s*<\/p>/g, '');
  html = html.replace(/<p>(<h[1-4]>)/g, '$1');
  html = html.replace(/(<\/h[1-4]>)<\/p>/g, '$1');
  html = html.replace(/<p>(<pre>)/g, '$1');
  html = html.replace(/(<\/pre>)<\/p>/g, '$1');
  html = html.replace(/<p>(<ul>)/g, '$1');
  html = html.replace(/(<\/ul>)<\/p>/g, '$1');
  html = html.replace(/<p>(<hr>)<\/p>/g, '$1');

  return html;
}

// ============================================
// AI Verification Guide (Machine-Readable)
// ============================================

